const paths={Roteiro:'M4 5h6l4 4h6v12h-6l-4-4H4z M10 5v12 M14 9v12',Transporte:'M3 11l7 1 6-8 3 1-3 8 5 4-1 2-7-2-4 4-2-1 1-5-5-2z',Acomodação:'M3 21V8l9-5 9 5v13 M8 21v-6h8v6 M7 9h1 M16 9h1 M7 12h1 M16 12h1',Passeio:'M12 22s8-8 8-13a8 8 0 1 0-16 0c0 5 8 13 8 13z M15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',Restaurante:'M5 3v7 M8 3v7 M11 3v7 M5 7h6 M8 10v11 M19 3c-5 3-5 10 0 10V3z M19 13v8',Perfil:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M4 21v-2a8 8 0 0 1 16 0v2'};
const icon=c=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[c]}"></path></svg>`;
const seed=[{id:1,category:'Transporte',title:'Chegada a Lisboa',time:'08:30',location:'Aeroporto Humberto Delgado · LIS',notes:'O começo de uma nova história. Próxima parada: a cidade!',day:0},{id:2,category:'Acomodação',title:'Deixar as malas no hotel',time:'10:00',location:'Seu hotel · Centro de Lisboa',notes:'Combine com a recepção para guardar a bagagem antes do check-in.',day:0},{id:3,category:'Restaurante',title:'Um primeiro sabor de Lisboa',time:'12:30',location:'Restaurante a escolher · Baixa',notes:'Hora de experimentar a culinária portuguesa.',day:0},{id:4,category:'Passeio',title:'Uma tarde pelas ruas de Alfama',time:'15:00',location:'Alfama · Lisboa',notes:'Caminhe sem pressa e aproveite os miradouros.',day:0}];
let entries,tripName,userName;try{entries=JSON.parse(localStorage.getItem('bv-entries'))||seed;tripName=localStorage.getItem('bv-trip')||'Lisboa, lá vamos nós.';userName=localStorage.getItem('bv-name')||'Viajante'}catch{entries=seed;tripName='Lisboa, lá vamos nós.';userName='Viajante'}
let section='Roteiro',day=0;const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2600)}
function save(){try{localStorage.setItem('bv-entries',JSON.stringify(entries))}catch{notify('Não foi possível salvar no navegador.')}render()}
function render(){ $('#tripTitle').textContent=tripName;$('#profileBtn').textContent=userName[0].toUpperCase();$('#nav').innerHTML=Object.keys(paths).map(c=>`<button aria-label="${c}" title="${c}" class="${section===c?'active':''}" data-section="${c}">${icon(c)}</button>`).join('');$('#nav').querySelectorAll('button').forEach(b=>b.onclick=()=>{if(b.dataset.section==='Perfil'){openProfile();return}section=b.dataset.section;render()});$('#sectionTitle').textContent=section==='Roteiro'?'Seu roteiro':section;const weekdays=['QUI','SEX','SÁB','DOM','SEG'];$('#days').innerHTML=weekdays.map((d,i)=>`<button class="day ${day===i?'active':''}" data-day="${i}">${d}<b>${12+i}</b>NOV</button>`).join('');$('#days').querySelectorAll('button').forEach(b=>b.onclick=()=>{day=+b.dataset.day;render()});const list=entries.filter(e=>e.day===day&&(section==='Roteiro'||section===e.category)).sort((a,b)=>a.time.localeCompare(b.time));$('#content').innerHTML=`<div class="day-heading"><h3>${['Quinta-feira','Sexta-feira','Sábado','Domingo','Segunda-feira'][day]}, ${12+day} de novembro</h3><span>${list.length} ${list.length===1?'plano':'planos'} · no seu ritmo</span></div>`+(list.length?`<div class="timeline">${list.map(e=>`<article class="entry"><div class="time">${esc(e.time)}</div><div class="entry-card"><div class="entry-icon">${icon(e.category)}</div><div class="entry-info"><div class="category">${esc(e.category)}</div><h4>${esc(e.title)}</h4><div class="location">⌖ &nbsp;${esc(e.location||'Local a definir')}</div>${e.notes?`<p class="note">${esc(e.notes)}</p>`:''}</div><button class="delete" aria-label="Excluir ${esc(e.title)}" title="Excluir plano" data-delete="${e.id}">×</button></div></article>`).join('')}</div>`:`<div class="empty">Um dia cheio de possibilidades.<br><button class="primary" id="emptyAdd">＋ Adicionar primeiro plano</button></div>`);$('#content').querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{entries=entries.filter(e=>e.id!==+b.dataset.delete);save();notify('Plano excluído')});if($('#emptyAdd'))$('#emptyAdd').onclick=openAdd;$('#activityCount').textContent=String(entries.length).padStart(2,'0');$('#progressText').textContent=entries.length+' planos';}
function openAdd(){ $('#entryForm').reset();$('#entryForm').elements.day.value=day;$('#entryForm').elements.category.value=section==='Roteiro'?'Passeio':section;$('#modal').showModal()}
$('#addBtn').onclick=openAdd;$('#timelineBtn').onclick=render;$('#closeModal').onclick=()=>$('#modal').close();$('#entryForm').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));entries.push({...data,day:+data.day,id:Date.now()});save();$('#modal').close();notify('Novo plano adicionado. Bora viver essa história!')};$('#editTrip').onclick=()=>{$('#tripForm').elements.tripName.value=tripName;$('#tripModal').showModal()};$('#tripForm').onsubmit=e=>{e.preventDefault();tripName=e.target.elements.tripName.value.trim();localStorage.setItem('bv-trip',tripName);$('#tripModal').close();render();notify('Viagem atualizada')};function openProfile(){$('#profileForm').elements.name.value=userName;$('#profileModal').showModal()}$('#profileBtn').onclick=openProfile;$('#profileForm').onsubmit=e=>{e.preventDefault();userName=e.target.elements.name.value.trim();localStorage.setItem('bv-name',userName);$('#profileModal').close();render();notify('Perfil atualizado')};render();
